var info = &quot;放开那位奶妈&quot;; 
var index = 0; 
var LIFETIME = 5; 
var STARTX = 32; 
var STARTY = Display.height-48; 
var redIndex = Utils.rand(0,info.length); 
function showInfo(){ 
 var a = $.createComment( 
 info.charAt(index), 
 { 
 motionGroup:[ 
 {alpha:{fromValue:0,toValue:1,lifeTime:1}}, 
 {alpha:{fromValue:1,toValue:1,lifeTime:LIFETIME}}, 
 {alpha:{fromValue:1,toValue:0,lifeTime:1}} 
 ], 
 x:STARTX + index * 20, y:STARTY,lifeTime:2+LIFETIME, color:0xffffff, fontsize:20 + Utils.rand(0,10)-5} 
 ); 
 a.bold = false; 
 a.rotation = Utils.rand(0,10)-5; 
 if(redIndex == index){ 
 a.textColor = 0xff0000; 
 } 
 index += 1; 
} 

interval(showInfo, 100, info.length);
